// ---------------------------------------------------------------------------
// deepFreeze — catalogues are shared, never mutated. Instances are cloned.
// ---------------------------------------------------------------------------
function deepFreeze(obj) {
  if (obj === null || typeof obj !== 'object' || Object.isFrozen(obj)) return obj;
  Object.freeze(obj);
  for (const key of Object.getOwnPropertyNames(obj)) deepFreeze(obj[key]);
  return obj;
}

/** 5th- through 9th-level spells, keyed by id. Frozen. */
export const SPELLS_HIGH = deepFreeze(RAW);

// ---------------------------------------------------------------------------
// Small pure helpers (no imports, no state) — convenience for UI and rules.
// ---------------------------------------------------------------------------

/** Every id in this half of the catalogue. */
export const SPELLS_HIGH_IDS = Object.freeze(Object.keys(SPELLS_HIGH));

/** Ids at a given spell level (5–9). */
export function highSpellsAtLevel(level) {
  return SPELLS_HIGH_IDS.filter((id) => SPELLS_HIGH[id].level === level);
}

/** Ids on a class list, optionally capped at a maximum spell level. */
export function highSpellsForList(list, maxLevel = 9) {
  return SPELLS_HIGH_IDS.filter((id) => SPELLS_HIGH[id].level <= maxLevel && SPELLS_HIGH[id].lists.includes(list));
}

/** Counts by level, for content audits: { 5:49, 6:34, ... }. */
export function highSpellCounts() {
  const out = {};
  for (const id of SPELLS_HIGH_IDS) {
    const l = SPELLS_HIGH[id].level;
    out[l] = (out[l] || 0) + 1;
  }
  return out;
}

